using System.Globalization;
using Microsoft.Data.Sqlite;
using NexaStation.Domain;
using NexaStation.Media.Hub;

namespace NexaStation.Infrastructure.Persistence;

public sealed class SqliteMediaPersistence(ISqliteConnectionFactory factory):IMediaPersistence
{
    public async Task SaveAssociationAsync(MediaAssociation value,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="""INSERT INTO MediaAssociations(Id,ScopeType,ScopeValue,MediaType,FileExtension,PlayerLibraryItemId,LaunchTargetId,ArgumentsTemplate,TrackingMode,HideFrontend,RestoreFrontend,CreatedAtUtc,UpdatedAtUtc) VALUES($id,$scope,$value,$media,$extension,$player,$target,$arguments,$tracking,$hide,$restore,$created,$updated) ON CONFLICT(Id) DO UPDATE SET ScopeType=excluded.ScopeType,ScopeValue=excluded.ScopeValue,MediaType=excluded.MediaType,FileExtension=excluded.FileExtension,PlayerLibraryItemId=excluded.PlayerLibraryItemId,LaunchTargetId=excluded.LaunchTargetId,ArgumentsTemplate=excluded.ArgumentsTemplate,TrackingMode=excluded.TrackingMode,HideFrontend=excluded.HideFrontend,RestoreFrontend=excluded.RestoreFrontend,UpdatedAtUtc=excluded.UpdatedAtUtc;""";Add(cmd,"$id",value.Id);Add(cmd,"$scope",(int)value.ScopeType);Add(cmd,"$value",value.ScopeValue);Add(cmd,"$media",value.MediaType is null?null:(int)value.MediaType);Add(cmd,"$extension",value.FileExtension);Add(cmd,"$player",value.PlayerLibraryItemId);Add(cmd,"$target",value.LaunchTargetId);Add(cmd,"$arguments",value.ArgumentsTemplate);Add(cmd,"$tracking",(int)value.TrackingMode);Add(cmd,"$hide",value.HideFrontend?1:0);Add(cmd,"$restore",value.RestoreFrontend?1:0);Add(cmd,"$created",Iso(value.CreatedAtUtc));Add(cmd,"$updated",Iso(value.UpdatedAtUtc));await cmd.ExecuteNonQueryAsync(cancellationToken);}
    public async Task<IReadOnlyList<MediaAssociation>> GetAssociationsAsync(CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT Id,ScopeType,ScopeValue,MediaType,FileExtension,PlayerLibraryItemId,LaunchTargetId,ArgumentsTemplate,TrackingMode,HideFrontend,RestoreFrontend,CreatedAtUtc,UpdatedAtUtc FROM MediaAssociations ORDER BY UpdatedAtUtc DESC;";await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken);List<MediaAssociation> values=[];while(await r.ReadAsync(cancellationToken))values.Add(new(r.GetString(0),(MediaAssociationScope)r.GetInt32(1),Get(r,2),r.IsDBNull(3)?null:(GalleryMediaType)r.GetInt32(3),Get(r,4),Get(r,5),Get(r,6),Get(r,7),(ApplicationTrackingMode)r.GetInt32(8),r.GetInt32(9)!=0,r.GetInt32(10)!=0,DateTime.Parse(r.GetString(11),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),DateTime.Parse(r.GetString(12),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind)));return values;}
    public async Task AddRecentAsync(RecentMediaEntry value,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="INSERT INTO RecentMedia(Id,GalleryMediaItemId,MediaType,OpenedAtUtc,PlayerLibraryItemId,LaunchMethod,TrackingConfidence) VALUES($id,$item,$type,$opened,$player,$method,$tracking);";Add(cmd,"$id",value.Id);Add(cmd,"$item",value.MediaItemId);Add(cmd,"$type",(int)value.MediaType);Add(cmd,"$opened",Iso(value.OpenedAtUtc));Add(cmd,"$player",value.PlayerLibraryItemId);Add(cmd,"$method",(int)value.LaunchMethod);Add(cmd,"$tracking",(int)value.TrackingConfidence);await cmd.ExecuteNonQueryAsync(cancellationToken);}
    public async Task<IReadOnlyList<RecentMediaEntry>> GetRecentAsync(int maximumResults,CancellationToken cancellationToken=default){await using SqliteConnection c=await factory.OpenAsync(cancellationToken);await using SqliteCommand cmd=c.CreateCommand();cmd.CommandText="SELECT Id,GalleryMediaItemId,MediaType,OpenedAtUtc,PlayerLibraryItemId,LaunchMethod,TrackingConfidence FROM RecentMedia ORDER BY OpenedAtUtc DESC LIMIT $maximum;";Add(cmd,"$maximum",Math.Clamp(maximumResults,1,100));await using SqliteDataReader r=await cmd.ExecuteReaderAsync(cancellationToken);List<RecentMediaEntry> values=[];while(await r.ReadAsync(cancellationToken))values.Add(new(r.GetString(0),Get(r,1),(GalleryMediaType)r.GetInt32(2),DateTime.Parse(r.GetString(3),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind),(MediaLaunchMethod)r.GetInt32(5),Get(r,4),(MediaTrackingConfidence)r.GetInt32(6)));return values;}
    private static void Add(SqliteCommand c,string name,object? value)=>c.Parameters.AddWithValue(name,value??DBNull.Value);private static string? Get(SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetString(i);private static string Iso(DateTime value)=>value.ToUniversalTime().ToString("O",CultureInfo.InvariantCulture);
}
